UPDATE PAYMENT_RECOVERY_HISTORY
SET RESULT = #{result},
    ERROR_CODE = #{errorCode},
    FINISHED_AT = #{finishedAt}
WHERE ID = #{historyId}
  AND FINISHED_AT IS NULL
